import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and single item base premiums ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");
  it.todo("quotes a plain sword for a customer with 0 years, first contract -- premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quotes a plain amulet for a customer with 0 years, first contract -- premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff for a customer with 0 years, first contract -- premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion for a customer with 0 years, first contract -- premium 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune -- base premium 25 G, premium 32 G (25 base + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("quotes a single moonstone -- base premium 25 G, premium 32 G (25 base + 2.5 first insurance + 5 fee, rounded up)");

  // --- Component building blocks ---
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block at 7)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks of alike components)");

  // --- Item-specific modifiers ---
  it.todo("quotes a cursed sword -- adds 50 G curse surcharge to the item base premium");
  it.todo("quotes a sword with enchantment 5 -- adds 30 G high-enchantment surcharge (threshold is inclusive)");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quotes a cursed sword with enchantment 5 -- both surcharges apply (50 G + 30 G)");

  // --- Policy-wide modifiers ---
  it.todo("quotes for a customer with 2 years with MHPCO -- 20 % loyalty discount applies (threshold is inclusive)");
  it.todo("quotes for a customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("applies the 10 % first insurance surcharge to the policy base premium of every quote, regardless of customer history");
  it.todo("applies a 15 % follow-up discount on the customer's second quote in a scenario");
  it.todo("applies the 15 % follow-up discount on the third quote as well");

  // --- Modifier scope on multi-item policies ---
  it.todo("quotes a cursed sword plus a plain amulet -- policy base 160 G, curse surcharge 50 G (50 % of the cursed item only) -> 210 G before further modifiers and fee");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote integration examples ---
  it.todo("integration: newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote errors ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- CLI exits non-zero, writes an error description to stderr, writes no results to stdout");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("claims a regular steel sword enchantment 3 with damage 500 G -- payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("claims a rune (insurance value 250 G) with damage 200 G -- payout 100 G (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("claims a steel sword enchantment 9 with damage 1000 G -- payout 400 G (50 % clause first, then deductible)");
  it.todo("claims a dragon-material sword enchantment 5 with damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("claims a dragon-material sword enchantment 9 with damage 1000 G -- payout 400 G (the 50 % rule wins over dragon material)");
  it.todo("claims a dragon-material sword with exactly enchantment 8 and damage 1000 G -- payout 400 G (threshold is inclusive)");
  it.todo("claims a steel sword enchantment 7 with damage 1000 G -- payout 900 G (below the high-enchantment threshold)");

  // --- Claim: insurance sum and cap ---
  it.todo("reports the remaining cap after a claim -- sword policy (sum 1000 G, cap 2000 G), claim 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("caps a second successive claim at the remaining cap -- second claim of 1500 G -> payout 600 G, remainingCap 0 G");
  it.todo("computes the insurance sum of a sword plus an amulet as 1600 G -- cap 3200 G");
  it.todo("computes the cap from unmodified insurance values -- cursed sword (premium 165 G) still has cap 2000 G");
  it.todo("computes the insurance sum of a sword plus 3 runes as 1750 G -- the block discount affects the premium only, cap 3500 G");

  // --- Claim: multiple items of the same type ---
  it.todo("computes the insurance sum of two swords as 2000 G -- cap 4000 G");
  it.todo("treats two sword damage entries against a two-sword policy as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero");

  // --- Claim: rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in MHPCO's favor)");

  // --- Claim errors ---
  it.todo("rejects a claim whose damage item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero with an error description on stderr");
  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero with an error description on stderr");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero with an error description on stderr");

  // --- CLI end-to-end ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order -- schema example: quote amulet then claim 200 G");
  it.todo("CLI resolves a claim's policy field as the zero-based index of the quote step that created the policy");
});
EOF
