'''const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function itemBasePremium(item: Item): number {
  return isComponent(item)
    ? COMPONENT_BASE_PREMIUM
    : MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * COMPONENT_BASE_PREMIUM;
}

